DECLARE
    v_max_id NUMBER;
BEGIN
    SELECT NVL(MAX(id), 0) INTO v_max_id FROM address; 
    EXECUTE IMMEDIATE 'ALTER TABLE address MODIFY ID GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH ' || (v_max_id + 1) || ')';
END;
/

